import React, { useState } from "react";
import { FiInbox, FiCheckSquare, FiShoppingBag, FiFileText, FiTruck, FiBell, FiTrash, FiX } from "react-icons/fi";

const NotificationsTab = () => {
  const [filter, setFilter] = useState("all");

  const [alerts, setAlerts] = useState([
    {
      id: 1,
      type: "request",
      title: "New Request Alert",
      message: "New buyer request received for 'Amoxicillin 500mg' in Indiranagar, Bengaluru.",
      time: "2026-06-14 22:30",
      icon: <FiInbox size={16} />,
      color: "#4F46E5",
    },
    {
      id: 2,
      type: "proposal",
      title: "Proposal Selected Alert",
      message: "Your proposal #PROP-9284 was selected for Request #REQ-2081! Action required: confirm order shipment.",
      time: "2026-06-14 21:15",
      icon: <FiCheckSquare size={16} />,
      color: "#10B981",
    },
    {
      id: 3,
      type: "order",
      title: "Order Confirmed Alert",
      message: "Order #ORD-8472 was confirmed by buyer Surbhi Gupta.",
      time: "2026-06-14 20:00",
      icon: <FiShoppingBag size={16} />,
      color: "#8B5CF6",
    },
    {
      id: 4,
      type: "prescription",
      title: "Prescription Upload Alert",
      message: "Action Required: Verify uploaded prescription file for Request #REQ-2094.",
      time: "2026-06-14 18:30",
      icon: <FiFileText size={16} />,
      color: "#EA580C",
    },
    {
      id: 5,
      type: "delivery",
      title: "Delivery Status Update",
      message: "Delivery status updated: Order #ORD-8461 was successfully delivered to Animesh Singh.",
      time: "2026-06-14 15:45",
      icon: <FiTruck size={16} />,
      color: "#06B6D4",
    },
  ]);

  const handleClearAlert = (id) => {
    setAlerts(alerts.filter((a) => a.id !== id));
  };

  const handleClearAll = () => {
    setAlerts([]);
  };

  const filteredAlerts = filter === "all" ? alerts : alerts.filter((a) => a.type === filter);

  return (
    <div className="notifications-tab animate-fade-in">
      <div className="d-flex justify-content-between align-items-center flex-wrap mb-4 gap-3">
        <h3 style={{ fontSize: "22px", fontWeight: "800", color: "#0F172A", margin: 0 }}>
          Notifications Center
        </h3>
        
        {alerts.length > 0 && (
          <button
            onClick={handleClearAll}
            className="btn btn-outline-danger btn-sm pill d-flex align-items-center gap-1 px-3"
            style={{ fontSize: "12px", border: "1px solid #FECACA" }}
          >
            <FiTrash size={12} /> Clear All
          </button>
        )}
      </div>

      <div className="row g-4">
        
        {/* Filters sidebar */}
        <div className="col-lg-3">
          <div className="dashboard-card p-3">
            <h5 className="font-14 fw-700 text-heading mb-3 px-2">Filter Alerts</h5>
            <div className="d-flex flex-column gap-1">
              {[
                { id: "all", label: "All Notifications", count: alerts.length },
                { id: "request", label: "New Requests", count: alerts.filter((a) => a.type === "request").length },
                { id: "proposal", label: "Proposal Alerts", count: alerts.filter((a) => a.type === "proposal").length },
                { id: "order", label: "Order Alerts", count: alerts.filter((a) => a.type === "order").length },
                { id: "prescription", label: "Prescriptions", count: alerts.filter((a) => a.type === "prescription").length },
                { id: "delivery", label: "Delivery Updates", count: alerts.filter((a) => a.type === "delivery").length },
              ].map((item) => (
                <button
                  key={item.id}
                  onClick={() => setFilter(item.id)}
                  className="w-100 text-start border-0 py-2 px-3 rounded-3 d-flex justify-content-between align-items-center"
                  style={{
                    fontSize: "13px",
                    fontWeight: "600",
                    background: filter === item.id ? "#F9F5FF" : "transparent",
                    color: filter === item.id ? "#A847F0" : "#475569",
                    transition: "all 0.2s",
                  }}
                >
                  <span>{item.label}</span>
                  <span
                    className={`badge rounded-pill ${
                      filter === item.id ? "bg-primary text-white" : "bg-light text-secondary"
                    }`}
                    style={{ fontSize: "10px", backgroundColor: filter === item.id ? "#A847F0" : "" }}
                  >
                    {item.count}
                  </span>
                </button>
              ))}
            </div>
          </div>
        </div>

        {/* Alerts feed */}
        <div className="col-lg-9">
          <div className="dashboard-card p-4">
            <h4 style={{ fontSize: "16px", fontWeight: "700", color: "#0F172A", marginBottom: "20px" }}>
              Alert History
            </h4>

            <div className="d-flex flex-column gap-3">
              {filteredAlerts.length > 0 ? (
                filteredAlerts.map((alert) => (
                  <div
                    key={alert.id}
                    className="p-3 border rounded-3 d-flex align-items-start gap-3 position-relative"
                    style={{ transition: "all 0.2s" }}
                  >
                    <div
                      style={{
                        width: "36px",
                        height: "36px",
                        borderRadius: "50%",
                        backgroundColor: `${alert.color}15`,
                        color: alert.color,
                        display: "flex",
                        alignItems: "center",
                        justifyContent: "center",
                        flexShrink: 0,
                      }}
                    >
                      {alert.icon}
                    </div>

                    <div style={{ flexGrow: 1, paddingRight: "24px" }}>
                      <div className="d-flex align-items-center gap-2 flex-wrap">
                        <h5 className="font-14 fw-700 text-heading mb-0">{alert.title}</h5>
                        <span style={{ fontSize: "11px", color: "#94A3B8" }}>{alert.time}</span>
                      </div>
                      <p className="mb-0 mt-1 small text-muted leading-relaxed" style={{ color: "#475569", lineHeight: "1.4" }}>
                        {alert.message}
                      </p>
                    </div>

                    <button
                      onClick={() => handleClearAlert(alert.id)}
                      className="border-0 bg-transparent text-muted position-absolute end-0 top-0 mt-3 me-3"
                      style={{ cursor: "pointer" }}
                      title="Dismiss Alert"
                    >
                      <FiX size={14} />
                    </button>
                  </div>
                ))
              ) : (
                <div className="text-center py-5 text-muted fw-bold">
                  <FiBell size={36} className="mb-2 text-muted" />
                  <p className="mb-0">No notifications found.</p>
                </div>
              )}
            </div>
          </div>
        </div>

      </div>
    </div>
  );
};

export default NotificationsTab;
